catalog_script_client.script:
//Created by: Rita Ramteke
//Purpose: To populate Email Address and Manager Name

function onChange(control, oldValue, newValue, isLoading) {
    // If the form is just loading, do nothing
    if (isLoading) {
        return;
    }

    // If the employee name is cleared out, clear all auto-populated fields
    if (newValue === '') {
        g_form.clearValue('email_address');
        g_form.clearValue('manager_name');
        return;
    }

    // Fetch the user record from the backend using the employee_name variable
    g_form.getReference('employee_name', populateUserFields);

    // Callback function to handle the retrieved user data
    function populateUserFields(userRecord) {
        if (userRecord) {
            // 1. Set the employee email address
            if (userRecord.email) {
                g_form.setValue('email_address', userRecord.email);
            } else {
                g_form.clearValue('email_address');
            }

            // 2. Set the manager name
            if (userRecord.manager) {
                g_form.setValue('manager_name', userRecord.manager);
            } else {
                g_form.clearValue('manager_name'); 
            }
        }
    }
}
